function renderNumber(x) {
  if (typeof x === "string") {
    return x;  // What happens with inf and nan
  }
  if (Math.abs(x) > 1e12) {
    // Use scientific notation
    return x.toExponential(3);
  } if (Math.abs(x) > 1e6) {
    return x.toLocaleString();  // Put commas in the number
  }
  if (isInteger(x * 1000)) {
    return x.toString();
  }
  // Round to 4 decimal places
  return x.toFixed(4);
}

